// Normalise the caller's inputs, and mint the run id.
//
// AN OMITTED INPUT IS AN UNBOUND VARIABLE, NOT A NULL. When a caller leaves `dryRun`
// out entirely, the START node has no such output, the parameter's expression resolves
// to nothing, and the script does not receive the variable at all - referencing it dies
// with `No such property: dryRun for class: Script_<hash>`. `?:` cannot save a name
// that was never bound, so every optional input is read through `binding.hasVariable`.
//
// This is the second half of the shared contract's input rule. That rule says real
// callers send EMPTY STRINGS for what they did not fill; they also sometimes send
// nothing at all, and the two fail in completely different places.
//
// An unusable periodId becomes a SENTINEL rather than an empty filter. The fetch
// downstream then keeps one property and one operator whatever the caller sent, which
// is what lets the builder draw its filter and the index analyser read it - an empty
// or absent filter would silently fetch every Period instead of none.

def opt = { String name -> binding.hasVariable(name) ? binding.getVariable(name) : null }

String pid = opt('periodId') == null ? '' : String.valueOf(opt('periodId')).trim()
boolean inputOk = !pid.isEmpty()

// "" is missing, not false. A caller that omits dryRun gets the SAFE answer: compute
// and report, write nothing. Writing pay is opt-in, never the default.
String dr = opt('dryRun') == null ? '' : String.valueOf(opt('dryRun')).trim().toLowerCase()
boolean dry = dr.isEmpty() ? true : (dr == 'true')

int limit = 1000
String pl = opt('pageLimit') == null ? '' : String.valueOf(opt('pageLimit')).trim()
if (!pl.isEmpty()) {
    try { limit = Integer.parseInt(pl) } catch (Exception e) { limit = 1000 }
}
if (limit < 1) limit = 1
if (limit > 5000) limit = 5000

// How many distinct keys one staged read's IN filter may carry. The reads are keyed on
// the previous stage's output, so this is the bound on the JOIN rather than on the page:
// a period touching more distinct payees than this needs calculating in chunks, and the
// fold refuses with KEY_SET_TOO_LARGE rather than sending a filter nobody sized.
int cap = 5000
String kc = opt('keyCap') == null ? '' : String.valueOf(opt('keyCap')).trim()
if (!kc.isEmpty()) {
    try { cap = Integer.parseInt(kc) } catch (Exception e) { cap = 5000 }
}
if (cap < 1) cap = 1
if (cap > 20000) cap = 20000

// The engine mints the run id; the caller cannot supply one. That is what makes the
// UNIQUE key on CalculationRun.runId un-hittable without a pre-check fetch, and the
// reason there is no pre-check node in this flow.
long now = System.currentTimeMillis()
String runId = 'RUN-' + now + '-' + Long.toHexString(new Random(now).nextInt(0x1000000))

return [
    periodId : inputOk ? pid : '__invalid_input__',
    inputOk  : inputOk,
    dryRun   : dry,
    pageLimit: limit,
    keyCap   : cap,
    runId    : runId,
    startedAt: now,
]

// Decide whether this period may be calculated at all, and hand the window down.
//
// Three refusals, each with its own caller-actionable status, because "it did not run"
// is not an answer anybody can act on:
//
//   INVALID_INPUT     the caller sent no periodId
//   PERIOD_NOT_FOUND  they sent one no Period carries
//   PERIOD_NOT_OPEN   the period is CLOSED, PAID or already CALCULATING
//
// CLOSED and PAID are the audit boundary — recalculating a paid month is how a number
// somebody has already been paid against silently changes. CALCULATING means another
// run holds it.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

List periods = rows(periodRows)

if (!(inputOk instanceof Boolean ? inputOk : String.valueOf(inputOk) == 'true')) {
    return [ok: false, status: 'INVALID_INPUT', message: 'periodId is required']
}
if (periods.isEmpty()) {
    return [ok: false, status: 'PERIOD_NOT_FOUND', message: "no Period with id ${periodId}".toString()]
}

def period = periods[0]
String st = String.valueOf(p(period, 'status'))
if (st != 'OPEN') {
    return [ok: false, status: 'PERIOD_NOT_OPEN',
            message: "period ${p(period, 'name')} is ${st}; only an OPEN period may be calculated".toString()]
}

def s = p(period, 'startDate'), e = p(period, 'endDate')
if (s == null || e == null) {
    return [ok: false, status: 'PERIOD_NOT_USABLE',
            message: "period ${p(period, 'name')} has no start or end date".toString()]
}

return [
    ok         : true,
    status     : 'OK',
    message    : '',
    periodName : String.valueOf(p(period, 'name')),
    windowStart: ((Number) s).longValue(),
    windowEnd  : ((Number) e).longValue(),
]

// Stage 1 -> 2: the distinct payee NAMES this period's deals actually mention.
//
// This is the hinge of the whole redesign. Before it, the flow read every Payee,
// Position, PositionAttribute and assignment in the org whether the period touched them
// or not - so the cost grew with HEADCOUNT instead of with the work. Now each fetch is
// filtered by the keys the previous stage proved it needs.
//
// It stays SET-based, one fetch per stage, and never one fetch per row. Resolving a name
// per transaction would be ~4 round trips x 2,917 rows for one month of NA data, and
// "no API call inside a per-item loop" is the rule that exists to stop exactly that.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

int cap = ((Number) keyCap).intValue()
Set names = new LinkedHashSet()
int noName = 0
for (t in rows(txnRows)) {
    Map attrs = (p(t, 'attrs') instanceof Map) ? (Map) p(t, 'attrs') : [:]
    def n = attrs.payeeName ?: attrs.teamMemberName
    String s = n == null ? '' : String.valueOf(n).trim()
    if (s.isEmpty()) { noName++; continue }
    names << s
}

// An empty IN matches NOTHING rather than being ignored, which is the safe direction -
// but the sentinel keeps the filter drawable and the counts honest.
List out = names.isEmpty() ? ['__none__'] : new ArrayList(names)

// A period touching more than `keyCap` distinct payees needs CHUNKING, not a bigger
// filter. Refusing is the honest answer; silently sending a 50,000-element IN is not.
return [names: out, count: names.size(), noName: noName, overflow: names.size() > cap]

// Stage 2 -> 3: the payee RECORD ids the names resolved to.
//
// Names that resolved to nothing are not reported here. A missing payee is a per-ROW
// verdict (UNRESOLVED_PAYEE, against one transaction) and the fold is where a row gets
// a verdict; a key extractor that refused here would fail the whole period over one
// unmapped name.

def rows(v) { return (v instanceof List) ? v : [] }
Set ids = new LinkedHashSet()
for (r in rows(payeeRows)) if (r.id != null) ids << r.id
return [payeeIds: ids.isEmpty() ? ['__none__'] : new ArrayList(ids), count: ids.size()]

// Stage 3 -> 4: the SEATS those payees held. Not every seat in the org - only the ones
// the period's deals can possibly credit.
//
// The date window is already applied server-side (effectiveStart <= windowEnd), so a
// seat somebody takes up next quarter never reaches the fold at all.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

int cap = ((Number) keyCap).intValue()
Set pos = new LinkedHashSet()
for (r in rows(occRows)) { def v = p(r, 'positionId'); if (v != null) pos << String.valueOf(v) }
return [positionIds: pos.isEmpty() ? ['__none__'] : new ArrayList(pos),
        count: pos.size(), overflow: pos.size() > cap]

// Stage 4 -> 5: the TITLE ids those seats carried in the window.
//
// Titles are fetched by id rather than whole because the title CODE is load-bearing - a
// rule stores `position.title == "T-AE"` and the seat stores a record id - so the wrong
// or missing code produces a rule that matches nothing and says nothing.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

Set titles = new LinkedHashSet()
Set terrs = new LinkedHashSet()
for (r in rows(attrRows)) {
    def t = p(r, 'titleId'); if (t != null) titles << String.valueOf(t)
    def y = p(r, 'territoryId'); if (y != null) terrs << String.valueOf(y)
}
return [titleIds: titles.isEmpty() ? ['__none__'] : new ArrayList(titles),
        territoryIds: terrs.isEmpty() ? ['__none__'] : new ArrayList(terrs),
        count: titles.size()]

// Stage 5 -> 6: every key a PlanAssignment might name this seat or title by.
//
// The live data names targets FOUR ways: a record id in `targetId`, a record id in
// `positionId`/`titleId`, and a business CODE in either. PLAN-1789032727380-3055 stores
// the string "POS-UK-AE-02" in a column typed as a foreign key to Position. So the key
// set is ids AND codes, and the fold accepts both.
//
// ONE FETCH, NOT THREE. The read is a STRUCTURED top-level OR -
// `targetId IN all OR positionId IN seats OR titleId IN titles` - which the builder draws
// and the index analyser reads, unlike a Groovy-built pill. The `startDate <= windowEnd`
// trim is dropped to keep it one flat OR: a seat has a handful of assignments over its
// life, and the fold judges every one of them by date anyway.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

Set posKeys = new LinkedHashSet()
for (v in rows(positionIds)) if (v != null && v != '__none__') posKeys << String.valueOf(v)
for (r in rows(posRows)) { def c = p(r, 'positionCode'); if (c != null) posKeys << String.valueOf(c) }

Set titleKeys = new LinkedHashSet()
for (v in rows(titleIds)) if (v != null && v != '__none__') titleKeys << String.valueOf(v)
for (r in rows(titleRows)) { def c = p(r, 'titleCode'); if (c != null) titleKeys << String.valueOf(c) }

Set all = new LinkedHashSet(); all.addAll(posKeys); all.addAll(titleKeys)
def nn = { Set s -> s.isEmpty() ? ['__none__'] : new ArrayList(s) }
return [positionKeys: nn(posKeys), titleKeys: nn(titleKeys), allKeys: nn(all), count: all.size()]

// Stage 6 -> 7: the plans those assignments point at.
//
// Status is NOT filtered here. A plan that is Draft or out of force still has to come
// back, because "an assignment points at a plan that is not usable" and "no assignment
// exists at all" are different answers to the rep, and filtering by status would collapse
// them into the second one.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

Set ids = new LinkedHashSet()
for (r in rows(asgRows)) { def v = p(r, 'planId'); if (v != null) ids << String.valueOf(v) }
return [planIds: ids.isEmpty() ? ['__none__'] : new ArrayList(ids), count: ids.size()]

// Stage 7 -> 8: the credit rules those plans actually list.
//
// `Plan.creditRules` holds BUSINESS keys ("TEST-NA-CR-RENEWAL"), not record ids, so the
// Rule fetch filters on `properties.ruleId` - which already carries a unique index and
// therefore draws no index warning, unlike the `id IN` fetches upstream.
//
// A plan pointing at a ruleId no Rule record has is left to the fold to report as
// RULE_MISSING against the deals it would have credited. Dropping it here would lose
// which plan asked for it.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

Set keys = new LinkedHashSet()
for (r in rows(planRows)) {
    def list = p(r, 'creditRules')
    if (!(list instanceof List)) continue
    for (k in list) if (k != null) keys << String.valueOf(k)
}
return [ruleIds: keys.isEmpty() ? ['__none__'] : new ArrayList(keys), count: keys.size()]

// Stage 8 -> 9: what the RULES actually need read, and nothing else.
//
// Until the rules are known, every remaining read is a guess. Once they are, each one is
// either proven necessary or skipped entirely - a skipped read is a round trip that never
// happens, which is the only kind of fetch that costs nothing:
//
//   CreditType     only the codes the rules file credits under (creditType, rollupCreditType)
//   Territory      only if some condition asks about `position.territory`
//   Currency       only if some condition asks about `payee.currency`
//   hierarchy      only if some rule rolls up, and only as many hops as its rollupLevels
//
// The same rows are then read the same way they always were, so the fold's answer does not
// change - only the number of calls that produced its inputs.

def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }
def nn = { Set s -> s.isEmpty() ? ['__none__'] : new ArrayList(s) }

/** Mirrors CreditPass.levelsFrom, which is what the walk will actually honour. */
int levelsFrom(def raw) {
    if (raw == null) return 0
    String t = String.valueOf(raw).trim()
    if (t.equalsIgnoreCase('All ancestors')) return 100
    try { return Integer.parseInt(t) } catch (Exception e) { return 0 }
}

Set ctCodes = new LinkedHashSet()
boolean wantsTerritory = false
boolean wantsCurrency = false
int maxLevels = 0

for (r in rows(ruleRows)) {
    // Same admission test as the fold: a Rule it would ignore must not buy a read.
    if (p(r, 'ruleId') == null || p(r, 'stage') != 'credit') continue

    def cond = p(r, 'conditions')
    String text = cond == null ? '' : groovy.json.JsonOutput.toJson(cond)
    if (text.contains('position.territory')) wantsTerritory = true
    if (text.contains('payee.currency')) wantsCurrency = true

    Map values = (Map) (((Map) p(r, 'result'))?.values ?: [:])
    if (values.creditType != null) ctCodes << String.valueOf(values.creditType)
    if (String.valueOf(values.rollup) == 'true') {
        if (values.rollupCreditType != null) ctCodes << String.valueOf(values.rollupCreditType)
        maxLevels = Math.max(maxLevels, levelsFrom(values.rollupLevels))
    }
}

Set terrIds = new LinkedHashSet()
for (a in rows(attrRows)) { def v = p(a, 'territoryId'); if (v != null) terrIds << String.valueOf(v) }
Set ccyIds = new LinkedHashSet()
for (y in rows(payeeRows)) { def v = p(y, 'currencyId'); if (v != null) ccyIds << String.valueOf(v) }

int seats = ((Number) seatCount).intValue()
return [
    creditTypeCodes: nn(ctCodes),     readCreditTypes: !ctCodes.isEmpty(),
    territoryIds   : nn(terrIds),     readTerritories: wantsTerritory && !terrIds.isEmpty(),
    currencyIds    : nn(ccyIds),      readCurrencies : wantsCurrency && !ccyIds.isEmpty(),
    maxLevels      : maxLevels,       readLine       : maxLevels > 0 && seats > 0,
]

// One hop up the reporting line, and whether the rules need another.
//
// ONE FILE, FOUR NODES. Each hop binds one more `hier<N>` set and reads whatever is
// there through `binding.hasVariable` - an unbound parameter is not null on this
// platform, it does not exist, so `?:` cannot be used to make a parameter list optional.
//
// WHY HOPS AND NOT ONE FETCH. Rollup climbs an unknown number of levels, and the seats
// above a rep are not knowable from the rep's own row - each level has to be asked for.
// Reading the WHOLE PositionHierarchy table instead would put org size back into the
// cost, which is the thing the staged design removes.
//
// WHY `next`. The walk only climbs as far as the rules' largest rollupLevels. A plan that
// rolls up one level reads ONE hop; the branch in front of each later hop is closed by
// this flag, so those fetches never execute. Four hops is still the ceiling, and a rule
// asking for more than the tree the four hops read is REPORTED, never truncated.

def opt = { String n -> binding.hasVariable(n) ? binding.getVariable(n) : null }
def rows(v) { return (v instanceof List) ? v : [] }
def p(row, String k) { return ((Map) row?.properties)?.get(k) }

int hopNo = ((Number) hop).intValue()
int want = ((Number) levels).intValue()

Set seen = new LinkedHashSet()
for (v in rows(opt('seatIds'))) if (v != null) seen << String.valueOf(v)
// seatIds arrives as the sentinel list when there are no seats; it must not become a key.
seen.remove('__none__')

Set ancestors = new LinkedHashSet()
Set frontier = new LinkedHashSet()
for (name in ['hier1', 'hier2', 'hier3', 'hier4']) {
    def bound = opt(name)
    if (bound == null) continue
    frontier = new LinkedHashSet()          // only the LAST bound hop defines the frontier
    for (h in rows(bound)) {
        def parent = p(h, 'parentPositionId')
        if (parent == null) continue
        String s = String.valueOf(parent)
        ancestors << s
        if (!seen.contains(s)) frontier << s
    }
    seen.addAll(ancestors)
}

// The parents this hop found are level-`hopNo` ancestors; their parents are level hopNo+1.
boolean moreWanted = !frontier.isEmpty() && want > hopNo
List front = frontier.isEmpty() ? ['__none__'] : new ArrayList(frontier)
return [
    frontier   : front,
    next       : moreWanted && hopNo < 4,
    // A rule wants a level beyond the fourth and the tree still climbs: the walk did not
    // finish. Reported by the fold as HIERARCHY_TOO_DEEP rather than dropping the top.
    deeper     : moreWanted && hopNo >= 4,
    ancestors  : ancestors.isEmpty() ? ['__none__'] : new ArrayList(ancestors),
    count      : seen.size(),
]

